class MetadataBlock(unittest.TestCase):
    def test_metadata_block_becomes_frontmatter(self):
        out = from_gdoc_markdown(EXPORTED, LOCAL)
        self.assertTrue(out.startswith("---\n"))
        self.assertIn("title: 高中校舍願景論壇\n", out)
        self.assertIn("speaker: 張三\n", out)
        self.assertIn("date: 2026-08-01\n", out)
        self.assertNotIn("**講者：**", out)

    def test_recording_summary_heading_restored(self):
        out = from_gdoc_markdown(EXPORTED, LOCAL)
        self.assertIn("\n# Recording Summary\n", out)
        self.assertNotIn("# 高中校舍願景論壇", out)


class Footer(unittest.TestCase):
    def test_footer_restored_from_local(self):
        out = from_gdoc_markdown(EXPORTED, LOCAL)
        self.assertTrue(
            out.endswith("---\n*Generated by video_summary using google/gemini-2.5-pro*\n"),
            out[-120:],
        )

    def test_bare_rule_left_by_google_docs_is_not_duplicated(self):
        out = from_gdoc_markdown(EXPORTED, LOCAL)
        self.assertEqual(out.count("\n---\n"), 2)  # frontmatter close + footer rule


class LocalOnlyFields(unittest.TestCase):
    def test_gdoc_id_survives_the_round_trip(self):
        out = from_gdoc_markdown(EXPORTED, LOCAL)
        self.assertIn("gdoc_id: 1AbC_dEfGh\n", out)


class UneditedDoc(unittest.TestCase):
    def test_unedited_doc_reproduces_the_local_file_byte_for_byte(self):
        self.assertEqual(from_gdoc_markdown(EXPORTED, LOCAL), LOCAL)


if __name__ == "__main__":
    unittest.main()


