class Sync(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.mkdtemp()
        self.path = os.path.join(self.dir, "summary.md")
        with open(self.path, "w", encoding="utf-8") as f:
            f.write(LOCAL)
        self.out = io.StringIO()
        self.exported_calls = []

    def tearDown(self):
        shutil.rmtree(self.dir)

    def _exporter(self, text):
        def export(doc_id):
            self.exported_calls.append(doc_id)
            return text
        return export

    def _read(self):
        with open(self.path, encoding="utf-8") as f:
            return f.read()

    def test_confirmed_edit_is_written_to_the_local_file(self):
        edited = EXPORTED.replace("這場論壇討論了校舍改建。", "這場論壇討論了校舍改建與經費。")
        rc = gdoc_sync.sync(self.path, exporter=self._exporter(edited),
                            confirm=lambda: True, out=self.out)
        self.assertEqual(rc, 0)
        self.assertIn("校舍改建與經費。", self._read())

    def test_declined_edit_leaves_the_file_untouched(self):
        edited = EXPORTED.replace("這場論壇討論了校舍改建。", "這場論壇討論了校舍改建與經費。")
        rc = gdoc_sync.sync(self.path, exporter=self._exporter(edited),
                            confirm=lambda: False, out=self.out)
        self.assertEqual(rc, 0)
        self.assertEqual(self._read(), LOCAL)

    def test_identical_doc_reports_no_changes_without_asking(self):
        def refuse():
            raise AssertionError("should not prompt when there is nothing to apply")
        rc = gdoc_sync.sync(self.path, exporter=self._exporter(EXPORTED),
                            confirm=refuse, out=self.out)
        self.assertEqual(rc, 0)
        self.assertEqual(self._read(), LOCAL)
        self.assertIn("no changes", self.out.getvalue().lower())

    def test_doc_id_comes_from_the_frontmatter(self):
        gdoc_sync.sync(self.path, exporter=self._exporter(EXPORTED),
                       confirm=lambda: True, out=self.out)
        self.assertEqual(self.exported_calls, ["1AbC_dEfGh"])

    def test_explicit_doc_id_is_recorded_for_next_time(self):
        with open(self.path, "w", encoding="utf-8") as f:
            f.write(LOCAL.replace("gdoc_id: 1AbC_dEfGh\n", ""))
        rc = gdoc_sync.sync(self.path, doc_id="9ZyX", exporter=self._exporter(EXPORTED),
                            confirm=lambda: True, out=self.out)
        self.assertEqual(rc, 0)
        self.assertEqual(self.exported_calls, ["9ZyX"])
        self.assertIn("gdoc_id: 9ZyX", self._read())

    def test_missing_doc_id_is_an_error(self):
        with open(self.path, "w", encoding="utf-8") as f:
            f.write(LOCAL.replace("gdoc_id: 1AbC_dEfGh\n", ""))
        rc = gdoc_sync.sync(self.path, exporter=self._exporter(EXPORTED),
                            confirm=lambda: True, out=self.out)
        self.assertEqual(rc, 1)
        self.assertIn("--doc-id", self.out.getvalue())

    def test_from_file_skips_the_export(self):
        src = os.path.join(self.dir, "exported.md")
        with open(src, "w", encoding="utf-8") as f:
            f.write(EXPORTED.replace("校舍改建。", "校舍改建與經費。"))
        rc = gdoc_sync.sync(self.path, from_file=src, exporter=self._exporter(EXPORTED),
                            confirm=lambda: True, out=self.out)
        self.assertEqual(rc, 0)
        self.assertEqual(self.exported_calls, [])
        self.assertIn("校舍改建與經費。", self._read())

    def test_assume_yes_writes_without_prompting(self):
        edited = EXPORTED.replace("校舍改建。", "校舍改建與經費。")
        def refuse():
            raise AssertionError("should not prompt with assume_yes")
        rc = gdoc_sync.sync(self.path, exporter=self._exporter(edited),
                            confirm=refuse, assume_yes=True, out=self.out)
        self.assertEqual(rc, 0)
        self.assertIn("校舍改建與經費。", self._read())

    def test_diff_is_shown_before_asking(self):
        edited = EXPORTED.replace("校舍改建。", "校舍改建與經費。")
        gdoc_sync.sync(self.path, exporter=self._exporter(edited),
                       confirm=lambda: True, out=self.out)
        printed = self.out.getvalue()
        self.assertIn("-這場論壇討論了校舍改建。", printed)
        self.assertIn("+這場論壇討論了校舍改建與經費。", printed)


def simulate_google_docs(gdoc_md):
    """Model what Google Docs gives back after importing gdoc.py's output.

    Checked against a real round trip (a 128-line summary through Docs and
    back): every bullet comes back flattened to a single level and re-markered
    as "- ", each heading gains a blank line under it, list groups are split by
    blank lines, and the italic generator footer is swallowed, leaving the bare
    rule behind.
    """
    out = []
    for line in gdoc_md.split("\n"):
        if re.match(r"^\*Generated by .*\*\s*$", line):
            continue
        m = re.match(r"^[ \t]*[-*+][ \t]+(?P<text>\S.*)$", line)
        if m:
            if out and not out[-1].strip() is False and re.match(r"^#{1,6}\s", out[-1]):
                out.append("")
            out.append(f"- {m.group('text')}")
            continue
        if re.match(r"^#{1,6}\s", line):
            out.append(line)
            out.append("")
            continue
        if out and re.match(r"^- ", out[-1]) and line.strip() and not line.startswith("#"):
            out.append("")
        out.append(line)
    return re.sub(r"\n{3,}", "\n\n", "\n".join(out)).rstrip() + "\n"


LOCAL_LEGACY_TITLED = LOCAL_LEGACY.replace(
    "# Recording Summary\n", "# Recording Summary\n\n**高中校舍願景論壇摘要**\n")


class ForwardConverterContract(unittest.TestCase):
    """gdoc_sync relies on gdoc.py keeping gdoc_id out of the uploaded doc."""

    def test_gdoc_id_is_never_rendered_into_the_google_doc(self):
        uploaded = gdoc.to_gdoc_markdown(LOCAL)
        self.assertNotIn("gdoc_id", uploaded)
        self.assertNotIn("1AbC_dEfGh", uploaded)

    def test_numbered_section_is_not_mistaken_for_a_repeated_title(self):
        uploaded = gdoc.to_gdoc_markdown(LOCAL_LEGACY)
        self.assertIn("## 概述", uploaded)

    def test_repeated_bold_title_line_is_still_dropped(self):
        titled = LOCAL_LEGACY.replace(
            "# Recording Summary\n", "# Recording Summary\n\n**高中校舍願景論壇摘要**")
        uploaded = gdoc.to_gdoc_markdown(titled)
        self.assertNotIn("**高中校舍願景論壇摘要**", uploaded)


class FullRoundTrip(unittest.TestCase):
    def test_untouched_document_comes_back_unchanged(self):
        fixtures = (("simple", LOCAL), ("nested", LOCAL_NESTED), ("tight", LOCAL_TIGHT),
                    ("legacy", LOCAL_LEGACY), ("legacy-titled", LOCAL_LEGACY_TITLED))
        for name, local in fixtures:
            with self.subTest(fixture=name):
                exported = simulate_google_docs(gdoc.to_gdoc_markdown(local))
                self.assertEqual(from_gdoc_markdown(exported, local), local)

    def test_only_the_real_edit_shows_up_in_the_diff(self):
        exported = simulate_google_docs(gdoc.to_gdoc_markdown(LOCAL_NESTED))
        exported = exported.replace("民國 60 年興建", "民國 62 年興建")
        out = from_gdoc_markdown(exported, LOCAL_NESTED)
        diff = [l for l in difflib.unified_diff(
            LOCAL_NESTED.splitlines(), out.splitlines(), lineterm="", n=0)
            if l[:1] in "+-" and not l.startswith(("---", "+++"))]
        self.assertEqual(diff, ["-  - 民國 60 年興建", "+  - 民國 62 年興建"])


