class BlankLines(unittest.TestCase):
    def test_blank_line_after_heading_is_dropped_when_local_has_none(self):
        out = from_gdoc_markdown(EXPORTED_LOOSE, LOCAL_TIGHT)
        self.assertIn("## 概述\n本次會議由導師主持。", out)
        self.assertIn("## 內容詳述\n### 暑期準備\n", out)

    def test_blank_line_between_list_groups_is_dropped(self):
        out = from_gdoc_markdown(EXPORTED_LOOSE, LOCAL_TIGHT)
        self.assertIn("  - 練習自理。\n- **開學初期：**\n", out)

    def test_blank_line_after_heading_is_kept_when_local_has_one(self):
        out = from_gdoc_markdown(EXPORTED, LOCAL)
        self.assertIn("## 概述 Overview\n\n這場論壇", out)

    def test_blank_line_between_a_paragraph_and_its_list_is_dropped(self):
        out = from_gdoc_markdown(EXPORTED_LOOSE, LOCAL_TIGHT)
        self.assertIn("會議中完成以下分組：\n- **生活適應：**", out)

    def test_blank_line_before_a_heading_is_preserved(self):
        out = from_gdoc_markdown(EXPORTED_LOOSE, LOCAL_TIGHT)
        self.assertIn("本次會議由導師主持。\n\n## 內容詳述", out)


